/**
 * Local object storage (Block 03). Every key is generated by the server from validated UUIDs — never from a user's file name — so no
 * request can address a path outside the store. The deployment swaps this for an S3 adapter with the same key layout:
 *   uploads/<upload id>/part-<n>                    resumable upload parts (deleted after assembly)
 *   org/<org id>/videos/<video id>/source.<ext>     the assembled source file (written by the ingest worker)
 *   org/<org id>/videos/<video id>/thumbnail.jpg
 */
import { createHash, randomBytes } from "node:crypto";
import { once } from "node:events";
import { createWriteStream } from "node:fs";
import { mkdir, rename, rm } from "node:fs/promises";
import path from "node:path";
import type { Readable } from "node:stream";
import { finished } from "node:stream/promises";

/** how far past the declared part size a body is read (and discarded) before the request is cut off */
const DRAIN_LIMIT = 64 * 1024 * 1024;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export class LocalStore {
  constructor(readonly root: string) {}

  /** Resolve a store key to a path, refusing anything that escapes the root. */
  resolve(key: string): string {
    if (!/^[A-Za-z0-9_./-]+$/.test(key) || key.split("/").some((s) => s === ".." || s === "")) throw new Error(`invalid storage key ${key}`);
    const full = path.resolve(this.root, ...key.split("/"));
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("storage key escapes the store");
    return full;
  }

  uploadDir(uploadId: string): string {
    if (!UUID.test(uploadId)) throw new Error("upload id must be a UUID");
    return this.resolve(`uploads/${uploadId.toLowerCase()}`);
  }

  partKey(uploadId: string, n: number): string {
    if (!UUID.test(uploadId) || !Number.isInteger(n) || n < 1) throw new Error("invalid part");
    return `uploads/${uploadId.toLowerCase()}/part-${String(n).padStart(6, "0")}`;
  }

  /**
   * Stream `body` into the part file, counting and hashing as it goes. Throws PartTooLarge (temp file deleted) beyond `maxBytes`; a part
   * of any other wrong size is refused with PartSizeMismatch. Only an exactly-sized, fully written part replaces an earlier copy.
   */
  async writePart(uploadId: string, n: number, body: Readable, exactBytes: number, declaredSha256?: string): Promise<{ bytes: number; sha256: string }> {
    const final = this.resolve(this.partKey(uploadId, n));
    await mkdir(path.dirname(final), { recursive: true });
    const tmp = `${final}.tmp-${randomBytes(6).toString("hex")}`;
    const hash = createHash("sha256");
    const out = createWriteStream(tmp, { flags: "wx" });
    // a write error must never be an unhandled 'error' event: that ends the whole API process (a client dropping mid-part did, 2026-11-05)
    let outError: Error | null = null;
    out.on("error", (e) => { outError ??= e; });
    let bytes = 0;
    let tooLarge = false;
    try {
      // Read the request to its end even when it is too large (writing stops): destroying the request stream would leave the client
      // without the 413 answer. A body far beyond the declared size is cut off (DRAIN_LIMIT) by failing the request.
      for await (const chunk of body as AsyncIterable<Buffer>) {
        bytes += chunk.length;
        if (bytes > exactBytes) {
          tooLarge = true;
          if (bytes > exactBytes + DRAIN_LIMIT) throw new PartTooLarge();
          continue;
        }
        if (outError) throw outError;
        hash.update(chunk);
        if (!out.write(chunk)) await once(out, "drain");
      }
      out.end();
      await finished(out);
      if (outError) throw outError;
    } catch (e) {
      // the client went away or the disk refused: close the file first (pending writes then fail quietly), then remove it
      if (!out.closed) { const closed = once(out, "close").catch(() => undefined); out.destroy(); await closed; }
      await rm(tmp, { force: true });
      throw e;
    }
    if (tooLarge) {
      await rm(tmp, { force: true });
      throw new PartTooLarge();
    }
    if (bytes !== exactBytes) {
      await rm(tmp, { force: true });
      throw new PartSizeMismatch(bytes, exactBytes);
    }
    const sha256 = hash.digest("hex");
    if (declaredSha256 && declaredSha256.toLowerCase() !== sha256) {        // damaged in transit: never replace a good earlier copy
      await rm(tmp, { force: true });
      throw new PartChecksumMismatch();
    }
    await rename(tmp, final);
    return { bytes, sha256 };
  }

  async removeUpload(uploadId: string): Promise<void> {
    await rm(this.uploadDir(uploadId), { recursive: true, force: true });
  }
}

export class PartTooLarge extends Error {
  constructor() { super("part larger than declared"); }
}

export class PartChecksumMismatch extends Error {
  constructor() { super("part checksum mismatch"); }
}

export class PartSizeMismatch extends Error {
  constructor(readonly got: number, readonly expected: number) { super(`part has ${got} bytes, expected ${expected}`); }
}
